update integration.systems set config=config||'{"identity":"program_plan_code"}'::jsonb,updated_at=now() where code='ca_ns_nscc_programs';
update pipeline.sources s set metadata=metadata||'{"course_identity_scheme":"nscc_program_plan_code","identity_semantics":"first-party program_plan_code; program_code retained as secondary descriptive code"}'::jsonb,updated_at=now() from integration.systems i where s.system_id=i.id and i.code='ca_ns_nscc_programs';
update pipeline.ca_source_qualifications q set course_identity_scheme='nscc_program_plan_code',stable_program_id_proof='first-party programme detail meta program_plan_code; more specific than reused program_code and independent of title/URL',notes='NSCC program_code was proven non-unique across plans before APPLY; identity promoted to program_plan_code. No title/name identity and no NS Courses were written under the rejected key.',updated_at=now() from pipeline.sources s join integration.systems i on i.id=s.system_id where q.source_id=s.id and i.code='ca_ns_nscc_programs';
